SYSTEM_V1 = (pathlib.Path("../c2f/llm.py").read_text(encoding="utf-8")
             .split('SYSTEM = """', 1)[1].split('"""', 1)[0])

K, UNCOVERED, BQ = 0.5, 0.6, 1 / 3

def tri_q(lo, mode, hi, q):
    lo, mode, hi = sorted((lo, mode, hi))
    if hi == lo: return lo
    f = (mode - lo) / (hi - lo)
    return lo + math.sqrt(q*(hi-lo)*(mode-lo)) if q <= f else hi - math.sqrt((1-q)*(hi-lo)*(hi-mode))

